import Foundation

/// Finds emoji by the words of their English names and their tags, from the bundled `emoji-keywords.json`
/// (generated by `scripts/make-emoji-data.py` from Emojibase), for the emoji panel's search (ruling M3-R15).
///
/// - **Words:** the query is lowercased and split into words at every character that isn't a letter or a digit, as the
///   keywords were. An emoji matches when every query word begins one of its keywords.
/// - **Ranking:** each query word matches an emoji exactly (a keyword equals it), by the beginning of a name word, or by
///   the beginning of a tag only. An emoji ranks by its weakest word: all-exact first, then name, then tag.
///   Within each of those, Recent's emoji first, most recent first, then the catalog's order.
/// - **Speed:** it runs on every keystroke, so the keywords sit in one byte buffer, compared as UTF-8 with no
///   per-keyword strings, and each call makes one pass over the catalog.
///
/// Nothing is cached here: `EmojiSearchStore` holds it for the keyboard process.
public struct EmojiSearch: Sendable {
    public enum LoadError: Error {
        case missingFile(String)
        /// An emoji whose value isn't a list of label words and a list of tag words.
        case malformed(String)
    }

    /// One emoji's keywords: those numbered `first..<end`, its name's words before `labelEnd`.
    private struct Entry: Sendable {
        var first: Int32, labelEnd: Int32, end: Int32
    }

    /// How a query word matches an emoji, best first: a keyword equal to it, the beginning of a name word, the
    /// beginning of a tag, or nothing.
    private enum Match: UInt8, Comparable {
        case exact, label, tag, miss

        static func < (a: Match, b: Match) -> Bool { a.rawValue < b.rawValue }
    }

    /// Every keyword's UTF-8, one after another. Keyword k is `bytes[keywordStarts[k]..<keywordStarts[k + 1]]`.
    private let bytes: [UInt8]
    private let keywordStarts: [Int32]
    private let entries: [Entry]
    /// Each emoji's index in `entries`, by its exact base string as `emoji.json` spells it.
    private let indexByBase: [String: Int32]
    /// The same, by `EmojiPreferences.key`, for Recent's variants and other spellings. The bundled bases' keys are
    /// all different.
    private let indexByKey: [String: Int32]

    /// A search over `keywords`, keyed by base emoji: each its name's words and its tags' other words, lowercase.
    init(keywords: [String: (label: [String], tags: [String])]) {
        var bytes: [UInt8] = []
        var keywordStarts: [Int32] = [0]
        var entries: [Entry] = []
        var indexByBase: [String: Int32] = [:]
        var indexByKey: [String: Int32] = [:]
        entries.reserveCapacity(keywords.count)
        indexByBase.reserveCapacity(keywords.count)
        indexByKey.reserveCapacity(keywords.count)
        // The order is the dictionary's, which can differ between runs; the results follow the catalog's order.
        for (base, words) in keywords {
            let first = Int32(keywordStarts.count - 1)
            for word in words.label + words.tags {
                bytes.append(contentsOf: word.utf8)
                keywordStarts.append(Int32(bytes.count))
            }
            let index = Int32(entries.count)
            let end = Int32(keywordStarts.count - 1)
            entries.append(Entry(first: first, labelEnd: first + Int32(words.label.count), end: end))
            indexByBase[base] = index
            let key = EmojiPreferences.key(base)
            if indexByKey[key] == nil { indexByKey[key] = index }
        }
        self.bytes = bytes
        self.keywordStarts = keywordStarts
        self.entries = entries
        self.indexByBase = indexByBase
        self.indexByKey = indexByKey
    }

    private struct File: Decodable {
        var keywords: [String: [[String]]]
    }

    /// Reads the bundled `emoji-keywords.json`. The caller holds the result; nothing is cached here.
    public static func load() throws -> EmojiSearch {
        guard let url = Bundle.module.url(forResource: "emoji-keywords", withExtension: "json") else {
            throw LoadError.missingFile("emoji-keywords.json")
        }
        let file = try JSONDecoder().decode(File.self, from: try Data(contentsOf: url))
        var keywords: [String: (label: [String], tags: [String])] = [:]
        keywords.reserveCapacity(file.keywords.count)
        for (base, lists) in file.keywords {
            guard lists.count == 2 else { throw LoadError.malformed(base) }
            keywords[base] = (lists[0], lists[1])
        }
        return EmojiSearch(keywords: keywords)
    }

    /// The emoji in `catalog` that match `query`, best first, at most `limit` of them; none for a query with no words.
    /// `recents` are Recent's emoji, most recent first, in any spelling: with a skin tone, or with or without U+FE0F.
    /// Only `catalog`'s items come back, so emoji newer than the iOS version running never do.
    public func results(for query: String, catalog: EmojiData, recents: [String], limit: Int = 60) -> [EmojiItem] {
        let words = Self.words(in: query)
        guard !words.isEmpty, limit > 0 else { return [] }
        var recentRanks: [Int32: Int] = [:]
        for (rank, emoji) in recents.enumerated() {
            if let index = indexByKey[EmojiPreferences.key(emoji)], recentRanks[index] == nil { recentRanks[index] = rank }
        }
        // By match: the recent ones with their rank, and the rest in catalog order.
        var recent: [[(rank: Int, item: EmojiItem)]] = [[], [], []]
        var others: [[EmojiItem]] = [[], [], []]
        bytes.withUnsafeBufferPointer { bytes in
            keywordStarts.withUnsafeBufferPointer { starts in
                for category in catalog.categories {
                    for item in category.items {
                        let index = indexByBase[item.base] ?? indexByKey[EmojiPreferences.key(item.base)]
                        guard let index else { continue }
                        let match = Self.match(words, entries[Int(index)], bytes: bytes, starts: starts)
                        guard match != .miss else { continue }
                        if let rank = recentRanks[index] {
                            recent[Int(match.rawValue)].append((rank, item))
                        } else {
                            others[Int(match.rawValue)].append(item)
                        }
                    }
                }
            }
        }
        var results: [EmojiItem] = []
        for tier in others.indices where results.count < limit {
            results += recent[tier].sorted { $0.rank < $1.rank }.map(\.item)
            results += others[tier].prefix(max(limit - results.count, 0))
        }
        return Array(results.prefix(limit))
    }

    /// The keywords of the emoji spelled exactly `base`; nil when it has none, as for a skin variant.
    func keywords(for base: String) -> (label: [String], tags: [String])? {
        guard let index = indexByBase[base] else { return nil }
        let entry = entries[Int(index)]
        let word = { (k: Int32) in
            String(decoding: bytes[Int(keywordStarts[Int(k)])..<Int(keywordStarts[Int(k) + 1])], as: UTF8.self)
        }
        return ((entry.first..<entry.labelEnd).map(word), (entry.labelEnd..<entry.end).map(word))
    }

    // MARK: Matching

    /// The query's words as UTF-8: lowercased, NFC like the keywords, split at every character that isn't a letter or
    /// a digit (so "t-rex" is "t" and "rex", and "heart," is "heart").
    private static func words(in query: String) -> [[UInt8]] {
        query.lowercased().precomposedStringWithCanonicalMapping
            .split { !($0.isLetter || $0.isNumber) }
            .map { Array($0.utf8) }
    }

    /// How well `entry` matches every word of the query: its weakest word's match, `.miss` if a word matches nothing.
    private static func match(
        _ words: [[UInt8]], _ entry: Entry, bytes: UnsafeBufferPointer<UInt8>, starts: UnsafeBufferPointer<Int32>
    ) -> Match {
        var weakest = Match.exact
        for word in words {
            let match = word.withUnsafeBufferPointer { Self.match($0, entry, bytes: bytes, starts: starts) }
            if match == .miss { return .miss }
            weakest = max(weakest, match)
        }
        return weakest
    }

    /// How `word` matches `entry`: the best of its keywords.
    private static func match(
        _ word: UnsafeBufferPointer<UInt8>, _ entry: Entry, bytes: UnsafeBufferPointer<UInt8>,
        starts: UnsafeBufferPointer<Int32>
    ) -> Match {
        var best = Match.miss
        for k in Int(entry.first)..<Int(entry.end) {
            let start = Int(starts[k]), length = Int(starts[k + 1]) - start
            guard length >= word.count, hasPrefix(word, in: bytes, at: start) else { continue }
            if length == word.count { return .exact }
            best = min(best, k < Int(entry.labelEnd) ? .label : .tag)
        }
        return best
    }

    /// Whether `bytes` from `start` begin with `prefix`. The caller checks that enough bytes follow.
    private static func hasPrefix(
        _ prefix: UnsafeBufferPointer<UInt8>, in bytes: UnsafeBufferPointer<UInt8>, at start: Int
    ) -> Bool {
        guard let base = bytes.baseAddress, let prefixBase = prefix.baseAddress else { return prefix.isEmpty }
        return memcmp(base + start, prefixBase, prefix.count) == 0
    }
}
